class OrderService {
    repo: OrderRepository

    init(repo: OrderRepository) {
        this.repo = repo
    }
}

fn findUser(id: String) -> Result<User, NotFoundError> {
    let user = this.repo.find(id)
    if user == null {
        return Result.err(NotFoundError("User not found"))
    }
    return Result.ok(user)
}

class CounterActor {
    var count: Int
    init() { this.count = 0 }
    fn handle(msg: String) -> Int {
        if msg == "inc" { this.count += 1 }
        return this.count
    }
}
